(7728895, 1272661, 70896, '<td valign="top">Weird shot, and I weirdly love it!</td>', 'Weird shot, and I weirdly love it!', '2022-08-29 17:19:11.000000', NULL, 1),
(7728948, 1272662, 114285, '<td valign="top">This wouldve been excellent for the numbers challenge also. I love the blurred reflection. Albeit its strange how I can still see mirroring underneath. For your sake I hope it is legal. Lighting is spot on.<br/> <br/>My top pick.</td>', 'This wouldve been excellent for the numbers challenge also. I love the blurred reflection. Albeit its strange how I can still see mirroring underneath. For your sake I hope it is legal. Lighting is spot on. My top pick.', '2022-08-30 21:57:37.000000', NULL, 1),
