(7728992, 1272667, 58728, '<td valign="top">My favorite!</td>', 'My favorite!', '2022-08-31 18:20:31.000000', NULL, 1),
(7728994, 1272629, 38162, '<td valign="top">My Nik Plugs have this type of vignette option- the rare times I use it I find it needs a manual adjustment to make it less intense.  Nice image and good toning. GL.</td>', 'My Nik Plugs have this type of vignette option- the rare times I use it I find it needs a manual adjustment to make it less intense.  Nice image and good toning. GL.', '2022-08-31 18:56:52.000000', NULL, 1),
